import numpy as np
one=np.ones_like(t)
pool={'1':one,'1/t':1/t,'log':np.log(t),'sqrt':np.sqrt(t),'t':t,'t2':t**2,'exp-t':np.exp(-t),'1/t2':1/t**2,'t3':t**3}
cols=[];names=[]
for pn,pf in pool.items():
    for an,af in [('1',one),('A',A),('A2',A**2)]:
        cols.append(pf*af); names.append(pn+'*'+an)
X=np.c_[tuple(cols)]
V=np.var(dA_dt)
def err(idx):
    Xs=X[:,idx]
    c=np.linalg.lstsq(Xs,dA_dt,rcond=None)[0]
    return np.mean((dA_dt-Xs@c)**2)/V, c
idx=list(range(X.shape[1]))
while len(idx)>3:
    best=None
    for j in idx:
        trial=[k for k in idx if k!=j]
        e,_=err(trial)
        if best is None or e<best[0]: best=(e,j)
    idx.remove(best[1])
    if len(idx)<12: print(len(idx), best[0], [names[k] for k in idx])
e,c=err(idx)
